const TaxCalculator={calculate(e,t={}){const a=CONFIG,i=t.taxYear||this.getCurrentTaxYear();let r=a.personalAllowance;if(e>1e5){const t=Math.floor((e-1e5)/2);r=Math.max(0,r-t)}const n=Math.max(0,e-r);let o=0,s=n;const m=a.taxBands||[{limit:37700,rate:.2},{limit:74870,rate:.4},{limit:1/0,rate:.45}];for(const e of m){if(s<=0)break;const t=Math.min(s,e.limit);o+=t*e.rate,s-=t}let l=0;const c=a.class4NIC||{},u=c.lowerThreshold??c.threshold??12570,f=c.upperThreshold??50270,h=c.mainRate??c.rate??.06,C=c.additionalRate??.02;e>u&&(l+=Math.max(0,Math.min(e,f)-u)*h,l+=Math.max(0,e-f)*C);const d=o+l,x=d/2,y=new Date,g=new Date(i.endYear+1,0,31),M=new Date(i.endYear+1,6,31);let p=d,R=0;t.firstYear||(p+=x,R=x);const w=Math.max(1,Math.ceil((g-y)/6048e5));return{taxYear:i,profit:e,personalAllowance:r,taxableProfit:n,incomeTax:o,class4NIC:l,totalLiability:d,paymentOnAccount:x,amountDueJan31:p,amountDueJul31:R,dueDates:{jan31:g,jul31:M},recommendedWeeklySave:p/w,weeksToJan31:w,effectiveRate:e>0?d/e*100:0}},getCurrentTaxYear(){const e=Utils.getTaxYearStart().getFullYear(),t=e+1;return{startYear:e,endYear:t,label:`${e}-${String(t).slice(2)}`}},async calculateFromData(e,t){const a=(await DB.db.appointments.where("date").between(e,t).and(e=>"cancelled"!==e.status&&"ordered"===e.outcome).toArray()).reduce((e,t)=>"number"==typeof t.commission&&t.commission>0?e+t.commission:e+this.estimateCommission(t.value||0),0),i=(await DB.getExpensesForPeriod(e,t)).reduce((e,t)=>e+(t.amount||0),0),r=(await DB.getTripsForPeriod(e,t)).reduce((e,t)=>e+(t.distanceKm||0),0),n=this.calculateMileageClaim(r),o=i+n,s=a-o;return{totalIncome:a,totalExpenses:i,mileageClaim:n,totalDeductible:o,profit:s,tax:this.calculate(s)}},estimateCommission(e){const t=Number(e||0);if(!(t>0))return 0;const a=CONFIG.commission||{};return"two_stage"===a.mode?t*Math.max(0,1-(a.saleReductionRate||0)/100)*Math.max(0,(a.netCommissionRate||0)/100):"simple"===a.mode?t*Math.max(0,(a.simpleRate||0)/100):"percentage"===a.type?t*Math.max(0,(a.rate||0)/100):t},getEffectiveCommissionRate(){const e=CONFIG.commission||{};if("two_stage"===e.mode){const t=1-(e.saleReductionRate||0)/100,a=(e.netCommissionRate||0)/100;return Math.max(0,t*a)}return"simple"===e.mode?Math.max(0,(e.simpleRate||0)/100):"percentage"===e.type?Math.max(0,(e.rate||0)/100):0},getRequiredWeeklySales(e){const t=this.getEffectiveCommissionRate(),a=Number(e||0);return t<=0||!(a>0)?0:a/t},calculateMileageClaim(e){const t=.621371*e;return Math.min(Math.max(0,t),1e4)*CONFIG.mileageRate+Math.max(0,t-1e4)*CONFIG.mileageRateOver},getMinHourlyRate(){if("number"==typeof CONFIG.minHourlyRate&&CONFIG.minHourlyRate>0)return{rate:CONFIG.minHourlyRate,isEstimate:!1};const e=(CONFIG.weeklyTarget||0)/25;return{rate:Math.round(100*e)/100,isEstimate:!0}},calculateVisitFloor({distanceKm:e=0,visitMinutes:t=0,driveMinutesOneWay:a=0}){const{rate:i,isEstimate:r}=this.getMinHourlyRate(),n=2*Math.max(0,e),o=this.calculateMileageClaim(n),s=Math.max(0,t)+2*Math.max(0,a),m=s/60*i,l=o+m,c=this.getEffectiveCommissionRate();return{roundTripKm:n,tripCost:o,totalMinutes:s,hourlyRate:i,hourlyRateIsEstimate:r,timeCost:m,minCommission:l,minSaleValue:c>0?l/c:null,effectiveRate:c}},async getRunningEstimate(){const e=this.getCurrentTaxYear(),t=new Date(e.startYear,3,6).toISOString(),a=(new Date).toISOString();return await this.calculateFromData(t,a)},formatSummary(e){const{tax:t}=e;return{income:Utils.formatCurrency(e.totalIncome),expenses:Utils.formatCurrency(e.totalExpenses),mileage:Utils.formatCurrency(e.mileageClaim),profit:Utils.formatCurrency(e.profit),incomeTax:Utils.formatCurrency(t.incomeTax),class4NIC:Utils.formatCurrency(t.class4NIC),taxDue:Utils.formatCurrency(t.totalLiability),jan31:Utils.formatCurrency(t.amountDueJan31),jul31:Utils.formatCurrency(t.amountDueJul31),weeklySave:Utils.formatCurrency(t.recommendedWeeklySave),effectiveRate:t.effectiveRate.toFixed(1)+"%",weeksLeft:t.weeksToJan31}}};
